const motionPreference = typeof matchMedia === "function" ? matchMedia("(prefers-reduced-motion: reduce)") : null;
return {
  draw(ctx, s) {
    const { width, end, height, high, max, pal, monet, dark, pointer } = s;
    const reduced = motionPreference?.matches;
    const time = reduced ? 0 : s.time;
    const burst = reduced ? 0 : s.burst;
    // 背景底板（全轨道）
    const bg = ctx.createLinearGradient(0, 0, width, 0);
    bg.addColorStop(0, dark ? "rgba(12,16,28,0.88)" : "rgba(235,241,250,0.92)");
    bg.addColorStop(1, dark ? "rgba(18,24,40,0.88)" : "rgba(226,234,248,0.92)");
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, width, height);

    const cell = 7.2;
    const cols = Math.ceil(width / cell);
    const rows = 4;
    const sec = monet.enabled ? monet.secondary : pal;

    for (let r = 0; r < rows; r++) {
      const cy = 4.2 + r * 7.8;
      for (let c = 0; c < cols; c++) {
        const cx = 4 + c * cell + (r % 2) * 3.2;
        const inProgress = cx <= end;
        const dx = pointer.inside ? cx - pointer.x : 999;
        const dy = pointer.inside ? cy - pointer.y : 999;
        const mouseBoost = Math.max(0, 1 - Math.hypot(dx, dy) / 36);
        const edgeGlow = Math.max(0, 1 - Math.abs(cx - end) / 26);
        const wave = 0.5 + 0.5 * Math.sin(c * 0.45 - time * 2.6 + r * 0.9);

        let alpha = inProgress ? (0.28 + 0.42 * wave + 0.22 * high) : 0.08;
        alpha += mouseBoost * 0.65 + edgeGlow * (0.35 + max * 0.35) + burst * 0.35;
        const sz = 2.1 + (inProgress ? 1.15 : 0) + mouseBoost * 1.45 + edgeGlow * 0.9;

        ctx.fillStyle = mouseBoost > 0.35
          ? "#ffffff"
          : (inProgress ? (c % 5 === 0 ? sec.light(Math.min(1, alpha)) : pal.main(Math.min(1, alpha)))
                        : (dark ? "rgba(148,163,184,0.22)" : "rgba(71,85,105,0.18)"));

        ctx.save();
        ctx.translate(cx, cy - mouseBoost * 1.8);
        ctx.rotate(Math.PI / 4);
        ctx.fillRect(-sz * 0.5, -sz * 0.5, sz, sz);
        ctx.restore();
      }
    }
  }
};
